-- Fonction helper pour les notifications de type JOB côté client
local function ShowConcessNotification(content, isError, jobName)
    local societyInfo = TriggerServerCallback("core:get:societyInfo", jobName)
    local notifType = isError and 'ROUGE' or 'JOB'

    VFW.ShowNotification({
