-- ==================== GESTION DES CONCESSIONNAIRES ====================

local CONCESS_LIST = {}
local CONCESS_PEDS = {}
local CONCESS_SHOWCASE_VEHICLES = {} -- { [concessId] = { { entity, rotate }, ... } }
local SHOWCASE_SPIN_SPEED = 18.0

local function showcaseEntity(entry)
    if type(entry) == "table" then return entry.entity end
    return entry
end

local function deleteShowcaseVehicles(vehicles)
    if type(vehicles) ~= "table" then return end
    for _, entry in ipairs(vehicles) do
        local veh = showcaseEntity(entry)
        if veh and DoesEntityExist(veh) then
            DeleteEntity(veh)
        end
    end
end

local SHOWCASE_STATE_TAG = "concess_showcase"

-- Supprime tout véhicule "fantôme" à un point de showcase issu d'une session précédente
-- (cas où onResourceStop n'a pas pu nettoyer, ou crash). On combine deux signaux pour
-- éviter de toucher le véhicule légitime d'un joueur garé à proximité :
--   - state bag tag (fiable tant que le statebag survit)
--   - sinon : même modèle exact + position quasi identique (rayon 0.6m)
local function DeleteOrphanShowcaseAt(point, modelHash)
    local found = GetClosestVehicle(point.x, point.y, point.z, 2.5, modelHash, 70)
    if found == 0 or not DoesEntityExist(found) then
        return
    end

    local taggedShowcase = false
    local state = Entity(found).state
    if state and state[SHOWCASE_STATE_TAG] then
        taggedShowcase = true
    end

    if not taggedShowcase then
        local pos = GetEntityCoords(found)
        local dx = pos.x - point.x
        local dy = pos.y - point.y
        local dz = pos.z - point.z
        if (dx * dx + dy * dy + dz * dz) > (0.6 * 0.6) then
            return
        end
    end

    SetEntityAsMissionEntity(found, true, true)
    DeleteEntity(found)
end

-- Charger les concessionnaires au spawn du joueur
local function LoadConcessionnaires()
    local concessList = TriggerServerCallback("core:concess:getAll")

    if not concessList then
        return
    end

    -- Nettoyer les anciens éléments
    CleanupConcessionnaires()

    for _, concess in ipairs(concessList) do
        CONCESS_LIST[concess.id] = concess
        SetupConcessionnaire(concess)
    end
end

-- Nettoyer tous les éléments (PEDs, markers, etc.)
function CleanupConcessionnaires()
    for id, ped in pairs(CONCESS_PEDS) do
        if DoesEntityExist(ped) then
            DeleteEntity(ped)
        end
        CONCESS_PEDS[id] = nil
    end

    -- Nettoyer les véhicules de showcase
    for id, vehicles in pairs(CONCESS_SHOWCASE_VEHICLES) do
        deleteShowcaseVehicles(vehicles)
        CONCESS_SHOWCASE_VEHICLES[id] = nil
    end

    CONCESS_LIST = {}
end

-- Configurer un concessionnaire
function SetupConcessionnaire(concess)
    if not concess then return end

    local hasCatalog = concess.catalog and type(concess.catalog) == "table" and #concess.catalog > 0
    if hasCatalog then
        -- automatic = true → Toujours PED (mode auto forcé)
        -- automatic = false → PED seulement si aucun employé en service
        if concess.automatic then
            SpawnConcessPed(concess)
        else
            local hasEmployeesOnDuty = TriggerServerCallback("core:concess:areEmployeesOnDuty", concess.job)
            if not hasEmployeesOnDuty then
                SpawnConcessPed(concess)
            end
        end
    end

    SpawnShowcaseVehicles(concess)
end

-- Spawner le PED du concessionnaire
function SpawnConcessPed(concess)
    if CONCESS_PEDS[concess.id] then
        return
    end

    local pedModel = concess.pedModel or "a_m_y_business_01"
    local catalogPoint = concess.catalog[1]

    if not catalogPoint then
        return
    end

    local modelHash = joaat(pedModel)
    VFW.Streaming.RequestModel(modelHash)

    local ped = CreatePed(4, modelHash, catalogPoint.x, catalogPoint.y, catalogPoint.z, catalogPoint.h or 0.0, false, true)

    if DoesEntityExist(ped) then
        SetEntityInvincible(ped, true)
        SetBlockingOfNonTemporaryEvents(ped, true)
        FreezeEntityPosition(ped, true)
        SetPedCanRagdoll(ped, false)
        SetPedDiesWhenInjured(ped, false)

        CONCESS_PEDS[concess.id] = ped
    end

    SetModelAsNoLongerNeeded(modelHash)
end

-- Spawner les véhicules de showcase du concessionnaire
function SpawnShowcaseVehicles(concess)
    if not concess or not concess.id then return end
    if type(concess.showcase) ~= "table" or #concess.showcase == 0 then
        return
    end

    if CONCESS_SHOWCASE_VEHICLES[concess.id] then
        deleteShowcaseVehicles(CONCESS_SHOWCASE_VEHICLES[concess.id])
    end
    CONCESS_SHOWCASE_VEHICLES[concess.id] = {}

    for _, showcasePoint in ipairs(concess.showcase) do
        local modelName = showcasePoint and showcasePoint.model
        if type(modelName) == "string" and modelName ~= "" then
            local modelHash = joaat(modelName)
            if IsModelValid(modelHash) and IsModelAVehicle(modelHash) then
                local loaded = VFW.Streaming.RequestModel(modelHash)
                if loaded then
                    DeleteOrphanShowcaseAt(showcasePoint, modelHash)

                    local x = showcasePoint.x + 0.0
                    local y = showcasePoint.y + 0.0
                    local z = showcasePoint.z + 0.0
                    RequestCollisionAtCoord(x, y, z)
                    local foundGround, groundZ = GetGroundZFor_3dCoord(x, y, z + 2.0, false)
                    if foundGround then z = groundZ end

                    local vehicle = CreateVehicle(modelHash, x, y, z, showcasePoint.h or 0.0, false, false)
                    if DoesEntityExist(vehicle) then
                        SetEntityAsMissionEntity(vehicle, true, true)
                        SetVehicleOnGroundProperly(vehicle)
                        SetEntityInvincible(vehicle, true)
                        FreezeEntityPosition(vehicle, true)
                        SetVehicleDoorsLocked(vehicle, 2)
                        SetVehicleEngineOn(vehicle, false, true, true)
                        SetVehicleUndriveable(vehicle, true)
                        Entity(vehicle).state:set(SHOWCASE_STATE_TAG, true, false)

                        if showcasePoint.color then
                            local r = showcasePoint.color.r or 255
                            local g = showcasePoint.color.g or 255
                            local b = showcasePoint.color.b or 255
                            SetVehicleCustomPrimaryColour(vehicle, r, g, b)
                            SetVehicleCustomSecondaryColour(vehicle, r, g, b)
                        end

                        CONCESS_SHOWCASE_VEHICLES[concess.id][#CONCESS_SHOWCASE_VEHICLES[concess.id] + 1] = {
                            entity = vehicle,
                            rotate = showcasePoint.rotate == true,
                            heading = showcasePoint.h or GetEntityHeading(vehicle) or 0.0,
                        }
                    end
                    SetModelAsNoLongerNeeded(modelHash)
                end
            end
        end
    end
end

