-- Vérifier si le joueur est employé du concessionnaire
local function IsPlayerEmployee(concess)
    local xPlayer = VFW.GetPlayerData()
    if not xPlayer or not xPlayer.job then
        return false
    end
    return xPlayer.job.name == concess.job and xPlayer.job.onDuty
end

-- Cache pour IsPlayerEmployee (re-check toutes les 5 secondes)
local _employeeCache = {}
local _employeeCacheTime = 0

local function IsPlayerEmployeeCached(concess)
    local now = GetGameTimer()
    if now - _employeeCacheTime > 5000 then
        _employeeCache = {}
        _employeeCacheTime = now
    end
    if _employeeCache[concess.job] == nil then
        _employeeCache[concess.job] = IsPlayerEmployee(concess)
    end
    return _employeeCache[concess.job]
end

-- Vérifier si le concessionnaire est en mode automatique (PED actif ou mode auto forcé)
local function IsConcessAutomatic(concess)
    if concess.automatic then
        return true
    end
    -- Si pas en mode auto forcé, vérifier s'il y a des employés en service
    local hasEmployeesOnDuty = TriggerServerCallback("core:concess:areEmployeesOnDuty", concess.job)
    return not hasEmployeesOnDuty
end

-- Animation tablette
