local function StopTabletAnimation()
    local playerPed = PlayerPedId()

    -- Arrêter l'animation
    StopAnimTask(playerPed, tabletAnimDict, tabletAnim, 1.0)

    -- Supprimer la tablette prop
    if tabletProp and DoesEntityExist(tabletProp) then
        DeleteEntity(tabletProp)
        tabletProp = nil
    end
end

-- Fonction pour ouvrir le catalogue du concessionnaire
local function OpenConcessCatalog(concess)
    if not concess then
        return
    end

    currentConcess = concess

    -- Jouer l'animation tablette
    PlayTabletAnimation()

    -- Récupérer les catégories et véhicules depuis le serveur (filtrés par type de concessionnaire)
    local categories = TriggerServerCallback("core:concess:getCategories", concess.concessType)
    local allVehicles = TriggerServerCallback("core:concess:getVehicles", nil, concess.concessType)

    if not categories or #categories == 0 then
        ShowConcessNotification("Aucune catégorie de véhicule disponible", true, concess.job)
        return
    end

    -- Vérifier si le joueur est employé
    local isEmployee = IsPlayerEmployee(concess)
    local isAutomatic = IsConcessAutomatic(concess)

    -- Récupérer le stock si employé
    local stock = {}
    if isEmployee then
        stock = TriggerServerCallback("core:concess:getStock", concess.id) or {}
    end

    -- Formater les catégories pour l'UI
    local formattedCategories = {}
    for _, cat in ipairs(categories) do
        formattedCategories[#formattedCategories + 1] = {
            name = cat,
            label = cat:gsub("^%l", string.upper)
        }
    end

    -- Formater les véhicules pour l'UI
    local formattedVehicles = {}
    for category, vehicles in pairs(allVehicles) do
        formattedVehicles[category] = {}
        for _, vehData in pairs(vehicles) do
            local cdnImage = VFW.CDN_BASE .. "/vehicles/" .. vehData.model .. ".png"
            local fallbackImage = ("https://docs.fivem.net/vehicles/%s.webp"):format(vehData.model)
            formattedVehicles[category][#formattedVehicles[category] + 1] = {
                model = vehData.model,
                name = vehData.name,
                price = vehData.price,
                category = vehData.category,
                speed = math.floor(GetVehicleModelEstimatedMaxSpeed(GetHashKey(vehData.model)) * 3.6),
                seats = GetVehicleModelNumberOfSeats(GetHashKey(vehData.model)),
                image = cdnImage,
                imageFallback = fallbackImage
            }
        end
    end

    local dataSociety = TriggerServerCallback("core:get:societyInfo", concess.job)

    -- Ouvrir l'interface NUI
    VFW.Nui.Focus(true, false)


    SendNUIMessage({
        action = "concessCatalog:open",
        data = {
            concessId = concess.id,
            concessName = dataSociety.jobLabel,
            concessImage = dataSociety.image,
            categories = formattedCategories,
            vehicles = formattedVehicles,
            selectedCategory = categories[1],
            isEmployee = isEmployee,
            isAutomatic = isAutomatic,
            stock = stock
        }
    })
end

-- Fonction pour fermer le catalogue
local function CloseConcessCatalog()
    VFW.Nui.Focus(false, false)
    SendNUIMessage({
        action = "concessCatalog:close"
    })
    currentConcess = nil

    -- Arrêter l'animation tablette
    StopTabletAnimation()
end

