-- Callback NUI : Récupérer les joueurs proches (avec noms RP depuis le serveur)
RegisterNUICallback("concessCatalog:getNearbyPlayers", function(_, cb)
    local nearbyPlayerIds = {}
    local playerPed = PlayerPedId()
    local playerCoords = GetEntityCoords(playerPed)
    local maxDistance = 10.0

    -- Récupérer les IDs serveur des joueurs proches
    for _, playerId in ipairs(GetActivePlayers()) do
        if playerId ~= PlayerId() then
            local targetPed = GetPlayerPed(playerId)
            if DoesEntityExist(targetPed) then
                local targetCoords = GetEntityCoords(targetPed)
                local distance = #(playerCoords - targetCoords)

                if distance <= maxDistance then
                    local serverId = GetPlayerServerId(playerId)
                    nearbyPlayerIds[#nearbyPlayerIds + 1] = serverId
                end
            end
        end
    end

    -- Demander les noms RP au serveur
    local nearbyPlayers = TriggerServerCallback("core:concess:getNearbyPlayersNames", nearbyPlayerIds)
    cb(nearbyPlayers or {})
end)

