-- Cache des poids de coffre (kg) par modèle, alimenté par vehicleStorage:getStorageValues
local trunkWeightCache = {}

-- Callback NUI : Prévisualiser un véhicule
-- Récupère le poids de stockage du coffre (trunk_weight) depuis la config
-- vehicle_storage_config (callback existant `vehicleStorage:getStorageValues`).
RegisterNUICallback("concessCatalog:preview", function(data, cb)
    local model = data and data.model
    if type(model) ~= 'string' or model == '' then
        cb({ weight = 0 })
        return
    end

    if trunkWeightCache[model] ~= nil then
        local cached = trunkWeightCache[model]
        SendNUIMessage({
            action = "concessCatalog:vehicleWeight",
            data = { model = model, weight = cached }
        })
        cb({ model = model, weight = cached })
        return
    end

    CreateThread(function()
        local hash = GetHashKey(model)
        local values = TriggerServerCallback("vehicleStorage:getStorageValues", model, hash) or {}
        local trunkWeight = math.floor(tonumber(values.trunk_weight) or 0)

        trunkWeightCache[model] = trunkWeight
        SendNUIMessage({
            action = "concessCatalog:vehicleWeight",
            data = { model = model, weight = trunkWeight }
        })
        cb({ model = model, weight = trunkWeight })
    end)
end)

