-- Fonction pour vérifier si un point de spawn est libre
local function IsSpawnPointFree(point, radius)
    radius = radius or 3.0
    local vehicle = GetClosestVehicle(point.x, point.y, point.z, radius, 0, 70)
    return vehicle == 0 or not DoesEntityExist(vehicle)
end

-- Fonction pour trouver un point de spawn libre
local function FindFreeSpawnPoint(concess)
    local spawnPoints = concess.spawn or {}

    -- Essayer d'abord les points de spawn dédiés
    for _, point in ipairs(spawnPoints) do
        if point and point.x and point.y and point.z then
            if IsSpawnPointFree(point) then
                return point
            end
        end
    end

    -- Si aucun spawn dédié libre, essayer les points du catalogue
    local catalogPoints = concess.catalog or {}
    for _, point in ipairs(catalogPoints) do
        if point and point.x and point.y and point.z then
            if IsSpawnPointFree(point) then
                return point
            end
        end
    end

    return nil
end

-- Event : Véhicule de test spawné côté serveur
RegisterNetEvent("concess:testVehicleSpawned", function(netId, plate, concessId)
    local concess = CONCESS_LIST[concessId]
    if not concess then
        ShowConcessNotification("Erreur: concessionnaire introuvable.", true)
        return
    end

    -- Stocker le job pour les notifications futures
    currentTestConcessJob = concess.job

    -- Attendre que le véhicule soit synchronisé côté client
    local attempts = 0
    local vehicle = nil

    while attempts < 50 do
        vehicle = NetworkGetEntityFromNetworkId(netId)
        if vehicle and DoesEntityExist(vehicle) then
            break
        end
        Wait(100)
        attempts = attempts + 1
    end

    if not vehicle or not DoesEntityExist(vehicle) then
        ShowConcessNotification("Erreur lors de la synchronisation du véhicule.", true, concess.job)
        return
    end

    -- Configurer le véhicule côté client
    SetVehicleOnGroundProperly(vehicle)
    SetVehicleDoorsLocked(vehicle, 0)
    SetVehicleDoorsLockedForAllPlayers(vehicle, false)
    SetVehicleDoorsLockedForNonScriptPlayers(vehicle, false)
    SetVehicleNeedsToBeHotwired(vehicle, false)
    SetVehicleIsStolen(vehicle, false)

    currentTestVehicle = vehicle
    currentTestNetId = netId

    ShowConcessNotification("Véhicule de test sorti.", false, concess.job)
end)

-- Event : Véhicule de test supprimé côté serveur
RegisterNetEvent("concess:testVehicleDeleted", function()
    if currentTestVehicle and DoesEntityExist(currentTestVehicle) then
        -- Sortir le joueur du véhicule si dedans
        local playerPed = PlayerPedId()
        if GetVehiclePedIsIn(playerPed, false) == currentTestVehicle then
            TaskLeaveVehicle(playerPed, currentTestVehicle, 0)
            Wait(1500)
        end
    end

    currentTestVehicle = nil
    currentTestNetId = nil

    ShowConcessNotification("Véhicule de test rangé.", false, currentTestConcessJob)
    currentTestConcessJob = nil
end)

